import useNetworkTotalRoom from "./room/useNetworkTotalRoom";
import TotalLobby from "./TotalLobby";
import TotalTable from "./TotalTable";

export default function TotalGame({ onNavigate }) {
    const roomApi = useNetworkTotalRoom();

    if (roomApi.connectError) {
        return (
            <div className="mx-auto max-w-xl px-6 py-24 text-center">
                <p className="text-red-400">{roomApi.connectError}</p>
            </div>
        );
    }

    if (!roomApi.room || roomApi.room.phase === "lobby") {
        return (
            <TotalLobby
                room={roomApi.room}
                isHost={roomApi.isHost}
                createRoom={roomApi.createRoom}
                joinRoom={roomApi.joinRoom}
                listPublicRooms={roomApi.listPublicRooms}
                startGame={roomApi.startGame}
                onQuit={() => {
                    roomApi.leaveRoom();
                    onNavigate("catalogue");
                }}
            />
        );
    }

    return (
        <TotalTable
            view={roomApi.view}
            send={roomApi.send}
            onQuit={() => {
                roomApi.leaveRoom();
                onNavigate("catalogue");
            }}
            onRestart={() => roomApi.leaveRoom()}
        />
    );
}