import PlayingCard from "./PlayingCard";
import { constraintAllows, CONSTRAINT_LABEL } from "../engine/rules";

/**
 * Le marché : 4 cartes face visible. Il est renouvelé lorsqu'un cycle complet
 * se termine sans qu'aucune carte du marché n'ait été prise.
 */
export default function Market({ cards, canTake, constraint, onTake, declinedCount, playerCount }) {
    return (
        <section
            data-testid="market-zone"
            className="rounded-md border border-[#D4AF37]/15 bg-[#120D0F]/70 p-6 backdrop-blur-xl"
        >
            <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
                <span className="eyebrow-label">Marché — cycle en cours</span>
                <span
                    data-testid="market-renewal-hint"
                    className="text-[11px] tracking-[0.1em] text-white/45"
                >
                    {declinedCount}/{playerCount} joueurs n'ont rien pris — le marché est renouvelé
                    quand aucune carte du marché n'est piochée durant le cycle
                </span>
            </div>

            {constraint && (
                <p
                    data-testid="market-constraint"
                    className="mb-4 rounded border border-[#8C2F3C]/50 bg-[#2D0A14]/60 px-3 py-2 text-xs text-[#E58C97]"
                >
                    Contrainte active — {CONSTRAINT_LABEL[constraint]}
                </p>
            )}

            <div className="flex flex-wrap gap-4">
                {cards.length === 0 && (
                    <p className="text-sm text-white/40" data-testid="market-empty">
                        Marché vide.
                    </p>
                )}
                {cards.map((card, index) => {
                    const allowed = constraintAllows(constraint, card);
                    return (
                        <PlayingCard
                            key={card.id}
                            card={card}
                            size="lg"
                            layoutId={`card-${card.id}`}
                            testId={`market-card-${index}`}
                            dimmed={canTake && !allowed}
                            disabled={!canTake || !allowed}
                            onClick={canTake && allowed ? () => onTake(card) : undefined}
                        />
                    );
                })}
            </div>
        </section>
    );
}
