import { Circle, Crown, Hand as HandIcon, ShieldAlert, Sparkles } from "lucide-react";
import { motion } from "framer-motion";
import { CONSTRAINT_LABEL } from "../engine/rules";

export default function PlayersBar({ players, currentPlayerId, winnerId }) {
    return (
        <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4" data-testid="players-bar">
            {players.map((player) => {
                const isCurrent = player.id === currentPlayerId;
                const isWinner = winnerId === player.id;
                return (
                    <motion.div
                        key={player.id}
                        data-testid={`player-chip-${player.id}`}
                        layout
                        animate={{
                            y: isCurrent ? -3 : 0,
                            scale: isCurrent ? 1.015 : 1,
                        }}
                        transition={{ type: "spring", stiffness: 280, damping: 24 }}
                        className={`relative overflow-hidden rounded-xl border px-4 py-4 backdrop-blur-xl transition-colors duration-300 ${
                            isWinner
                                ? "border-[#D4AF37]/70 bg-[#1A1113]/95 shadow-[0_0_45px_rgba(212,175,55,0.18)]"
                                : isCurrent
                                  ? "border-[#D4AF37]/55 bg-[#1A1113]/95 shadow-[0_0_40px_rgba(212,175,55,0.12)]"
                                  : "border-white/[0.07] bg-[#120D0F]/60"
                        }`}
                    >
                        {isCurrent && (
                            <motion.div
                                aria-hidden="true"
                                className="absolute inset-x-0 top-0 h-px bg-[#D4AF37]"
                                animate={{ opacity: [0.35, 1, 0.35] }}
                                transition={{ duration: 1.8, repeat: Infinity, ease: "easeInOut" }}
                            />
                        )}

                        <div className="flex items-center gap-3">
                            <div className={`relative shrink-0 ${isCurrent ? "scale-110" : ""}`}>
                                <motion.div
                                    animate={isCurrent ? { boxShadow: ["0 0 0 rgba(212,175,55,0)", "0 0 26px rgba(212,175,55,0.28)", "0 0 0 rgba(212,175,55,0)"] } : {}}
                                    transition={{ duration: 2, repeat: Infinity }}
                                    className={`rounded-full ${isCurrent ? "ring-2 ring-[#D4AF37] ring-offset-2 ring-offset-[#120D0F]" : "ring-1 ring-white/10"}`}
                                >
                                    <img
                                        src={player.avatar}
                                        alt={`Avatar de ${player.name}`}
                                        className={`h-11 w-11 rounded-full object-cover ${player.connected === false ? "opacity-35 grayscale" : ""}`}
                                    />
                                </motion.div>
                                {isCurrent && (
                                    <span className="absolute -bottom-1 -right-1 flex h-5 w-5 items-center justify-center rounded-full border border-[#120D0F] bg-[#D4AF37] text-[#0A0708]">
                                        <Sparkles size={10} />
                                    </span>
                                )}
                            </div>

                            <div className="min-w-0 flex-1">
                                <div className="flex items-center gap-2">
                                    <span className={`truncate font-display text-lg ${isCurrent || isWinner ? "text-[#FAF9F6]" : "text-white/60"}`}>
                                        {player.name}
                                    </span>
                                    {isWinner && <Crown size={14} className="shrink-0 text-[#D4AF37]" />}
                                </div>
                                <div className="mt-1 flex flex-wrap items-center gap-2 text-[10px] uppercase tracking-[0.15em]">
                                    <span className={`inline-flex items-center gap-1 ${player.connected ? "text-emerald-400/75" : "text-white/25"}`}><Circle size={8} fill="currentColor" /> {player.connected ? "En ligne" : "Déconnecté"}</span>
                                    <span className="inline-flex items-center gap-1 text-white/35"><HandIcon size={10} /> {player.handCount} cartes</span>
                                    {isCurrent && (
                                        <span data-testid={`player-turn-${player.id}`} className="rounded-full border border-[#D4AF37]/45 bg-[#D4AF37]/8 px-2 py-0.5 text-[#D4AF37]">
                                            À lui
                                        </span>
                                    )}
                                    {player.tookThisCycle && (
                                        <span data-testid={`player-took-${player.id}`} className="rounded-full border border-white/10 px-2 py-0.5 text-white/40">
                                            A pris ce cycle
                                        </span>
                                    )}
                                </div>
                            </div>
                        </div>

                        {player.constraint && (
                            <p data-testid={`player-constraint-${player.id}`} className="mt-3 inline-flex items-center gap-1 text-[10px] text-[#E58C97]">
                                <ShieldAlert size={10} /> {CONSTRAINT_LABEL[player.constraint]}
                            </p>
                        )}
                    </motion.div>
                );
            })}
        </section>
    );
}
