/**
 * TOTAL — règles pures.
 * Aucune de ces fonctions ne dépend de React : elles sont directement
 * réutilisables par le backend commun Mascarade pour valider les actions.
 */

import { HAND_SIZE, SPECIAL, isNumberCard, formatTotal } from "./cards";

/**
 * Calcule l'expression STRICTEMENT de gauche à droite.
 * Il n'y a que des additions de valeurs signées : aucune priorité,
 * aucune multiplication/division.
 * @returns {{ result:number, steps:Array<{value:number, running:number}>, expression:string }}
 */
export function computeExpression(cards) {
    let running = 0;
    const steps = [];
    cards.forEach((card) => {
        const value = isNumberCard(card) ? card.value : 0;
        running += value;
        steps.push({ id: card.id, value, running });
    });
    const expression = cards
        .map((card, index) => {
            const value = isNumberCard(card) ? card.value : 0;
            if (index === 0) return formatTotal(value);
            return value < 0 ? `- ${Math.abs(value)}` : `+ ${value}`;
        })
        .join(" ");
    return { result: running, steps, expression };
}

/** Un TOTAL ne peut être annoncé qu'avec 5 cartes numériques. */
export function canDeclareTotal(hand) {
    return hand.length === HAND_SIZE && hand.every(isNumberCard);
}

/**
 * Une main atteint-elle son Total ?
 * L'ordre est purement visuel : le calcul de gauche à droite d'additions
 * de valeurs signées est commutatif, donc une main correspond à son Total
 * si et seulement si la somme de ses 5 cartes vaut la cible.
 */
export function handMatchesTotal(hand, target) {
    if (!canDeclareTotal(hand)) return false;
    return computeExpression(hand).result === target;
}

export const CONSTRAINT_LABEL = {
    [SPECIAL.POSITIF]: "Positif : uniquement une carte numérique positive",
    [SPECIAL.NEGATIF]: "Négatif : uniquement une carte numérique négative",
    [SPECIAL.SEUIL_PLUS]: "Seuil +3 : uniquement une carte +4 ou supérieure",
    [SPECIAL.SEUIL_MOINS]: "Seuil -3 : uniquement une carte -4 ou inférieure",
};

/** La contrainte active autorise-t-elle la prise de cette carte du marché ? */
export function constraintAllows(constraint, card) {
    if (!constraint) return true;
    if (!isNumberCard(card)) return false;
    switch (constraint) {
        case SPECIAL.POSITIF:
            return card.value > 0;
        case SPECIAL.NEGATIF:
            return card.value < 0;
        case SPECIAL.SEUIL_PLUS:
            return card.value >= 4;
        case SPECIAL.SEUIL_MOINS:
            return card.value <= -4;
        default:
            return true;
    }
}

/** Réordonne une main selon une liste d'ids (utilisé par reorderHand / attemptTotal). */
export function orderHandByIds(hand, ids) {
    const byId = new Map(hand.map((card) => [card.id, card]));
    const ordered = [];
    ids.forEach((id) => {
        if (byId.has(id)) {
            ordered.push(byId.get(id));
            byId.delete(id);
        }
    });
    byId.forEach((card) => ordered.push(card));
    return ordered;
}
