import { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Check, X, Trophy, Timer, Send } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

const DURATIONS_MS = { vf: 12000, qcm: 20000, qcmMulti: 25000, zoom: 25000, bac: 45000 };
const TILE_STYLES = [
    "from-[#33E1FF] to-[#2B8CFF]",
    "from-[#FF2E92] to-[#FF7A2E]",
    "from-[#7C4DFF] to-[#33E1FF]",
    "from-[#FFC93C] to-[#FF2E92]",
];

// Halo vert appliqué sur la bonne réponse (tuile) une fois la révélation lancée.
const CORRECT_HALO = "ring-4 ring-[#22C55E] shadow-[0_0_28px_rgba(34,197,94,0.6)]";
const WRONG_MINE_HALO = "ring-4 ring-[#FF2E92]/70";

export default function OneUpBoard({ view, answer, onQuit }) {
    const [now, setNow] = useState(Date.now());
    const [selectedMulti, setSelectedMulti] = useState([]);
    const [bacAnswers, setBacAnswers] = useState({});

    useEffect(() => {
        if (view?.phase !== "playing") return undefined;
        const id = setInterval(() => setNow(Date.now()), 150);
        return () => clearInterval(id);
    }, [view?.phase]);

    useEffect(() => {
        setSelectedMulti([]);
        setBacAnswers({});
    }, [view?.question?.id]);

    if (!view) return null;

    if (view.phase === "finished") {
        const podium = view.players.slice(0, 3);
        return (
            <div className="relative flex min-h-screen flex-col items-center justify-center overflow-hidden bg-[#05070A] px-6 py-16 text-center">
                <div className="pointer-events-none absolute -left-40 top-0 h-[520px] w-[520px] rounded-full bg-[#33E1FF]/10 blur-[120px]" />
                <div className="pointer-events-none absolute -right-40 bottom-0 h-[520px] w-[520px] rounded-full bg-[#FF2E92]/10 blur-[120px]" />

                <motion.div initial={{ opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} className="relative z-10 w-full max-w-lg">
                    <Trophy size={40} className="mx-auto text-[#33E1FF]" />
                    <p className="font-arcade mt-4 text-xs uppercase tracking-[0.3em] text-[#33E1FF]">Fin de la partie</p>
                    <h1 className="font-arcade mt-3 text-4xl font-bold text-white" data-testid="oneup-winner-name">
                        {podium[0]?.name} l'emporte !
                    </h1>

                    <div className="mt-10 space-y-2">
                        {view.players.map((p, i) => (
                            <div
                                key={p.id}
                                data-testid={`final-score-${p.id}`}
                                className={`flex items-center justify-between rounded-lg border px-4 py-3 text-left ${
                                    i === 0 ? "border-[#33E1FF]/50 bg-[#33E1FF]/10" : "border-white/10 bg-white/[0.03]"
                                }`}
                            >
                                <span className="font-arcade text-white">
                                    {i + 1}. {p.name}
                                </span>
                                <span className="font-arcade text-[#33E1FF]">{p.score} pts</span>
                            </div>
                        ))}
                    </div>

                    <Button
                        data-testid="oneup-quit-btn"
                        onClick={onQuit}
                        className="mt-8 h-12 w-full bg-gradient-to-r from-[#33E1FF] to-[#FF2E92] font-arcade font-semibold uppercase tracking-[0.14em] text-black hover:opacity-90"
                    >
                        Retour au catalogue
                    </Button>
                </motion.div>
            </div>
        );
    }

    const question = view.question;
    if (!question) return null;

    const duration = DURATIONS_MS[question.type] ?? 20000;
    const remainingMs = view.phase === "playing" ? Math.max(0, (view.questionEndsAt ?? now) - now) : 0;
    const progress = view.phase === "playing" ? Math.max(0, Math.min(1, remainingMs / duration)) : 0;
    const isReveal = view.phase === "reveal";
    const locked = view.hasAnswered || view.phase !== "playing";

    function handleAnswer(payload) {
        if (locked) return;
        answer(payload);
    }

    function toggleMultiOption(i) {
        setSelectedMulti((prev) => (prev.includes(i) ? prev.filter((x) => x !== i) : [...prev, i]));
    }

    function submitMulti() {
        handleAnswer({ selectedIndexes: selectedMulti });
    }

    function submitBac() {
        handleAnswer(bacAnswers);
    }

    return (
        <div className="relative min-h-screen overflow-hidden bg-[#05070A] px-6 py-10 md:px-12">
            <div className="pointer-events-none absolute -left-40 top-0 h-[520px] w-[520px] rounded-full bg-[#33E1FF]/10 blur-[120px]" />
            <div className="pointer-events-none absolute -right-40 bottom-0 h-[520px] w-[520px] rounded-full bg-[#FF2E92]/10 blur-[120px]" />

            <div className="relative mx-auto max-w-3xl">
                <div className="flex items-center justify-between">
                    <span className="font-arcade text-xs uppercase tracking-[0.3em] text-[#33E1FF]">
                        Question {view.questionIndex + 1} / {view.questionCount}
                    </span>
                    <span className="flex items-center gap-2 text-xs text-white/40">
                        <Timer size={13} /> {view.answersCount}/{view.players.length} ont répondu
                    </span>
                </div>

                <div className="mt-3 h-1.5 w-full overflow-hidden rounded-full bg-white/10">
                    <motion.div
                        className="h-full bg-gradient-to-r from-[#33E1FF] to-[#FF2E92]"
                        animate={{ width: `${progress * 100}%` }}
                        transition={{ ease: "linear", duration: 0.15 }}
                    />
                </div>

                {question.type === "bac" ? (
                    <BacRound question={question} view={view} isReveal={isReveal} locked={locked} bacAnswers={bacAnswers} setBacAnswers={setBacAnswers} submitBac={submitBac} />
                ) : (
                    <>
                        <AnimatePresence mode="wait">
                            <motion.h1
                                key={question.id}
                                initial={{ opacity: 0, y: 16 }}
                                animate={{ opacity: 1, y: 0 }}
                                className="font-arcade mt-10 text-center text-2xl font-bold leading-snug text-white md:text-3xl"
                                data-testid="oneup-question-text"
                            >
                                {question.question}
                            </motion.h1>
                        </AnimatePresence>

                        {question.type === "zoom" && (
                            <div className="mx-auto mt-6 h-56 w-full max-w-md overflow-hidden rounded-xl border border-white/10 bg-black">
                                <motion.img
                                    src={question.image}
                                    alt=""
                                    className="h-full w-full object-cover"
                                    animate={{ scale: isReveal ? 1 : 1 + progress * 2.5 }}
                                    transition={{ ease: "linear", duration: 0.15 }}
                                />
                            </div>
                        )}

                        {question.type === "vf" && (
                            <div className="mt-10 grid grid-cols-2 gap-4">
                                {[
                                    { label: "Vrai", value: true, style: TILE_STYLES[0] },
                                    { label: "Faux", value: false, style: TILE_STYLES[1] },
                                ].map((opt) => {
                                    const isCorrect = isReveal && opt.value === question.correctBool;
                                    const isMine = isReveal && view.myLastAnswer?.payload?.boolAnswer === opt.value;
                                    return (
                                        <button
                                            key={opt.label}
                                            type="button"
                                            data-testid={`oneup-answer-${opt.label}`}
                                            disabled={locked}
                                            onClick={() => handleAnswer({ boolAnswer: opt.value })}
                                            className={`relative h-24 rounded-xl bg-gradient-to-br font-arcade text-xl font-bold text-black transition-opacity ${opt.style} ${
                                                view.hasAnswered && !isReveal ? "opacity-40" : ""
                                            } ${isReveal && !isCorrect ? "opacity-30" : ""} ${isCorrect ? CORRECT_HALO : ""} ${
                                                isMine && !isCorrect ? WRONG_MINE_HALO : ""
                                            }`}
                                        >
                                            {opt.label}
                                            {isReveal && isCorrect && <Check className="absolute right-3 top-3" size={20} />}
                                            {isReveal && isMine && !isCorrect && <X className="absolute right-3 top-3" size={20} />}
                                        </button>
                                    );
                                })}
                            </div>
                        )}

                        {(question.type === "qcm" || question.type === "zoom") && (
                            <div className="mt-10 grid grid-cols-1 gap-4 sm:grid-cols-2">
                                {question.options.map((opt, i) => {
                                    const isCorrect = isReveal && i === question.correctIndex;
                                    const isMine = isReveal && view.myLastAnswer?.payload?.optionIndex === i;
                                    return (
                                        <button
                                            key={i}
                                            type="button"
                                            data-testid={`oneup-answer-${i}`}
                                            disabled={locked}
                                            onClick={() => handleAnswer({ optionIndex: i })}
                                            className={`relative flex h-20 items-center justify-center rounded-xl bg-gradient-to-br px-4 text-center font-arcade text-base font-semibold text-black transition-opacity ${TILE_STYLES[i % TILE_STYLES.length]} ${
                                                view.hasAnswered && !isReveal ? "opacity-40" : ""
                                            } ${isReveal && !isCorrect ? "opacity-30" : ""} ${isCorrect ? CORRECT_HALO : ""} ${
                                                isMine && !isCorrect ? WRONG_MINE_HALO : ""
                                            }`}
                                        >
                                            {opt}
                                            {isReveal && isCorrect && <Check className="absolute right-3 top-3" size={18} />}
                                            {isReveal && isMine && !isCorrect && <X className="absolute right-3 top-3" size={18} />}
                                        </button>
                                    );
                                })}
                            </div>
                        )}

                        {question.type === "qcmMulti" && (
                            <div className="mt-10">
                                <p className="mb-3 text-center text-xs uppercase tracking-widest text-white/40">
                                    Plusieurs réponses possibles
                                </p>
                                <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                                    {question.options.map((opt, i) => {
                                        const isCorrectOpt = isReveal && question.correctIndexes.includes(i);
                                        const wasSelected = isReveal
                                            ? (view.myLastAnswer?.payload?.selectedIndexes || []).includes(i)
                                            : selectedMulti.includes(i);
                                        return (
                                            <button
                                                key={i}
                                                type="button"
                                                data-testid={`oneup-multi-${i}`}
                                                disabled={locked}
                                                onClick={() => toggleMultiOption(i)}
                                                className={`relative flex items-center gap-3 rounded-xl border px-4 py-3 text-left transition-colors ${
                                                    wasSelected ? "border-[#33E1FF] bg-[#33E1FF]/10" : "border-white/10 bg-white/[0.03]"
                                                } ${isReveal && isCorrectOpt ? CORRECT_HALO : ""} ${
                                                    isReveal && wasSelected && !isCorrectOpt ? WRONG_MINE_HALO : ""
                                                }`}
                                            >
                                                <Checkbox checked={wasSelected} disabled className="pointer-events-none" />
                                                <span className="font-arcade text-sm text-white">{opt}</span>
                                                {isReveal && isCorrectOpt && <Check className="absolute right-3 top-3 text-[#22C55E]" size={16} />}
                                            </button>
                                        );
                                    })}
                                </div>
                                {!locked && (
                                    <Button
                                        data-testid="oneup-multi-submit-btn"
                                        onClick={submitMulti}
                                        className="mt-4 h-11 w-full bg-gradient-to-r from-[#33E1FF] to-[#FF2E92] font-arcade font-semibold uppercase tracking-[0.14em] text-black hover:opacity-90"
                                    >
                                        <Send size={14} className="mr-2" /> Valider mes réponses
                                    </Button>
                                )}
                            </div>
                        )}
                    </>
                )}

                {view.hasAnswered && view.phase === "playing" && (
                    <p className="mt-6 text-center text-sm text-white/40">Réponse envoyée — en attente des autres joueurs…</p>
                )}

                {isReveal && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="mt-8 space-y-2">
                        {view.players.map((p) => (
                            <div
                                key={p.id}
                                data-testid={`reveal-player-${p.id}`}
                                className={`flex items-center justify-between rounded-lg border px-4 py-2 text-sm transition-colors ${
                                    p.lastCorrect
                                        ? "border-[#22C55E]/70 bg-[#22C55E]/10 shadow-[0_0_18px_rgba(34,197,94,0.25)]"
                                        : p.lastAnswered
                                        ? "border-white/10 bg-white/[0.03]"
                                        : "border-white/5 bg-white/[0.01] opacity-50"
                                }`}
                            >
                                <span className="flex items-center gap-2 text-white/80">
                                    {p.lastCorrect && <Check size={13} className="text-[#22C55E]" />}
                                    {p.name}
                                    {!p.lastAnswered && <span className="text-xs text-white/30">(sans réponse)</span>}
                                </span>
                                <span className="font-arcade text-[#33E1FF]">{p.score} pts</span>
                            </div>
                        ))}
                    </motion.div>
                )}
            </div>
        </div>
    );
}

function BacRound({ question, view, isReveal, locked, bacAnswers, setBacAnswers, submitBac }) {
    return (
        <div className="mt-10">
            <p className="text-center text-xs uppercase tracking-[0.3em] text-white/40">Baccalauréat gaming</p>
            <p className="font-arcade mt-2 text-center text-6xl font-bold text-[#33E1FF]" data-testid="oneup-bac-letter">
                {question.letter}
            </p>

            {!isReveal ? (
                <div className="mx-auto mt-8 max-w-md space-y-4">
                    {question.categories.map((cat) => (
                        <div key={cat.key}>
                            <Label className="text-xs uppercase tracking-widest text-white/50">{cat.label}</Label>
                            <Input
                                data-testid={`oneup-bac-${cat.key}`}
                                disabled={locked}
                                value={bacAnswers[cat.key] || ""}
                                onChange={(e) => setBacAnswers((prev) => ({ ...prev, [cat.key]: e.target.value }))}
                                placeholder={`Commence par ${question.letter}...`}
                                className="mt-1 border-white/10 bg-black/40 text-white"
                            />
                        </div>
                    ))}
                    {!locked && (
                        <Button
                            data-testid="oneup-bac-submit-btn"
                            onClick={submitBac}
                            className="h-11 w-full bg-gradient-to-r from-[#33E1FF] to-[#FF2E92] font-arcade font-semibold uppercase tracking-[0.14em] text-black hover:opacity-90"
                        >
                            <Send size={14} className="mr-2" /> Valider
                        </Button>
                    )}
                </div>
            ) : (
                <div className="mx-auto mt-8 max-w-lg space-y-6">
                    {(view.bacReveal || []).map((cat) => (
                        <div key={cat.key}>
                            <p className="text-xs uppercase tracking-widest text-white/40">{cat.label}</p>
                            <div className="mt-2 space-y-1.5">
                                {cat.entries.map((entry, i) => (
                                    <div
                                        key={i}
                                        className={`flex items-center justify-between rounded-lg border px-3 py-2 text-sm ${
                                            entry.status === "unique"
                                                ? "border-[#22C55E]/70 bg-[#22C55E]/10 shadow-[0_0_16px_rgba(34,197,94,0.2)]"
                                                : entry.status === "duplicate"
                                                ? "border-[#FFC93C]/50 bg-[#FFC93C]/5"
                                                : "border-white/5 bg-white/[0.01] opacity-50"
                                        }`}
                                    >
                                        <span className="text-white/80">{entry.playerName}</span>
                                        <span className="font-arcade text-white/60">{entry.text || "—"}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}
