import { useState } from "react";
import { ArrowLeft, ArrowRight } from "lucide-react";
import PlayingCard from "./PlayingCard";
import { computeExpression } from "../engine/rules";
import { isNumberCard } from "../engine/cards";

/**
 * Main du joueur : réordonnable (drag & drop + flèches) — l'ordre affiché est
 * EXACTEMENT l'ordre utilisé pour le calcul de gauche à droite.
 */
export default function Hand({
    cards,
    onReorder,
    onCardClick,
    selectedId = null,
    showRunning = true,
    lockedCardId = null,
}) {
    const [dragId, setDragId] = useState(null);
    const { steps } = computeExpression(cards);

    const move = (from, to) => {
        if (to < 0 || to >= cards.length || from === to) return;
        const next = [...cards];
        const [card] = next.splice(from, 1);
        next.splice(to, 0, card);
        onReorder(next.map((c) => c.id));
    };

    const handleDrop = (index) => {
        if (!dragId) return;
        const from = cards.findIndex((c) => c.id === dragId);
        setDragId(null);
        move(from, index);
    };

    return (
        <div className="flex flex-wrap items-end gap-3" data-testid="my-hand">
            {cards.map((card, index) => (
                <div key={card.id} className="flex flex-col items-center gap-1.5">
                    <PlayingCard
                        card={card}
                        layoutId={`card-${card.id}`}
                        testId={`hand-card-${index}`}
                        selected={selectedId === card.id}
                        disabled={lockedCardId === card.id}
                        onClick={lockedCardId === card.id ? undefined : onCardClick ? () => onCardClick(card) : undefined}
                        draggableProps={{
                            draggable: true,
                            onDragStart: () => setDragId(card.id),
                            onDragEnd: () => setDragId(null),
                            onDragOver: (e) => e.preventDefault(),
                            onDrop: () => handleDrop(index),
                        }}
                    />
                    {showRunning && (
                        <span
                            data-testid={`hand-running-${index}`}
                            className="text-[10px] font-semibold tracking-[0.12em] text-white/40"
                        >
                            {isNumberCard(card) ? `= ${steps[index].running}` : "—"}
                        </span>
                    )}
                    <div className="flex items-center gap-1">
                        <button
                            type="button"
                            aria-label="Déplacer la carte vers la gauche"
                            data-testid={`hand-move-left-${index}`}
                            onClick={() => move(index, index - 1)}
                            className="rounded border border-white/10 p-1 text-white/50 transition-colors duration-200 hover:border-[#D4AF37]/50 hover:text-[#D4AF37]"
                        >
                            <ArrowLeft size={11} />
                        </button>
                        <button
                            type="button"
                            aria-label="Déplacer la carte vers la droite"
                            data-testid={`hand-move-right-${index}`}
                            onClick={() => move(index, index + 1)}
                            className="rounded border border-white/10 p-1 text-white/50 transition-colors duration-200 hover:border-[#D4AF37]/50 hover:text-[#D4AF37]"
                        >
                            <ArrowRight size={11} />
                        </button>
                    </div>
                </div>
            ))}
        </div>
    );
}
