import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { Play, Users, Copy, Check, Crown, RefreshCw, ChevronLeft, ChevronRight, Clock3, Eye, FileText, Sparkles, Settings2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";

const AVATARS = Array.from({ length: 10 }, (_, index) => ({
    id: index + 1,
    src: `${process.env.PUBLIC_URL || ""}/avatars/avatar_${index + 1}.jpeg`,
}));

function loadIdentity() {
    try {
        return JSON.parse(localStorage.getItem("mascarade-identity")) || {};
    } catch {
        return {};
    }
}
function saveIdentity(identity) {
    localStorage.setItem("mascarade-identity", JSON.stringify(identity));
}

export default function TotalLobby({
    room,
    isHost,
    createRoom,
    joinRoom,
    listPublicRooms,
    startGame,
    onQuit,
}) {
    const saved = loadIdentity();
    const savedAvatar = AVATARS.some((item) => item.src === saved.avatar) ? saved.avatar : AVATARS[0].src;
    const [name, setName] = useState(saved.name || "");
    const [avatar, setAvatar] = useState(savedAvatar);
    const [avatarIndex, setAvatarIndex] = useState(() => Math.max(0, AVATARS.findIndex((item) => item.src === savedAvatar)));
    const [screen, setScreen] = useState("identity"); // identity | menu | join | public
    const [joinCode, setJoinCode] = useState("");
    const [isPublic, setIsPublic] = useState(true);
    const [specialCards, setSpecialCards] = useState(true);
    const [showHandTotal, setShowHandTotal] = useState(true);
    const [showGameLog, setShowGameLog] = useState(true);
    const [turnTimerSeconds, setTurnTimerSeconds] = useState(45);
    const [publicRooms, setPublicRooms] = useState([]);
    const [error, setError] = useState(null);
    const [copied, setCopied] = useState(false);

    const identityValid = name.trim().length >= 2;

    function confirmIdentity() {
        if (!identityValid) return;
        saveIdentity({ name: name.trim(), avatar });
        setScreen("menu");
    }

    async function handleCreate() {
        setError(null);
        const res = await createRoom({ name: name.trim(), avatar, isPublic, specialCards, showHandTotal, showGameLog, turnTimerSeconds });
        if (!res.ok) setError(res.error || "Impossible de créer le salon.");
    }

    async function handleJoin(code) {
        setError(null);
        const res = await joinRoom({ code: code.trim().toUpperCase(), name: name.trim(), avatar });
        if (!res.ok) setError(res.error || "Impossible de rejoindre ce salon.");
    }

    async function refreshPublicRooms() {
        setPublicRooms(await listPublicRooms());
    }

    useEffect(() => {
        if (screen === "public") refreshPublicRooms();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [screen]);

    function copyCode() {
        navigator.clipboard.writeText(room.code);
        setCopied(true);
        setTimeout(() => setCopied(false), 1500);
    }

    // --- Salle d'attente : on est déjà dans un salon (room.phase === "lobby") ---
    if (room) {
        return (
            <div className="mx-auto max-w-2xl px-6 py-16 md:py-24">
                <motion.div initial={{ opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6 }}>
                    <span className="eyebrow-label">Salon d'attente</span>
                    <div className="mt-3 flex items-center gap-4">
                        <h1 className="font-display text-5xl font-semibold tracking-tight">{room.code}</h1>
                        <button
                            type="button"
                            data-testid="copy-room-code-btn"
                            onClick={copyCode}
                            className="flex h-9 w-9 items-center justify-center rounded-md border border-white/10 text-white/60 hover:border-[#D4AF37]/40 hover:text-[#D4AF37]"
                        >
                            {copied ? <Check size={15} /> : <Copy size={15} />}
                        </button>
                    </div>
                    <p className="mt-2 text-sm text-white/50">Partage ce code à tes amis pour qu'ils rejoignent.</p>

                    <div className="mt-8 space-y-2 rounded-md border border-[#D4AF37]/15 bg-[#120D0F]/70 p-6">
                        {room.seats.map((seat) => (
                            <div
                                key={seat.playerId}
                                data-testid={`seat-${seat.playerId}`}
                                className="flex items-center gap-3 rounded-md border border-white/[0.06] bg-[#0A0708]/60 px-4 py-3"
                            >
                                <img
                                    src={seat.avatar}
                                    alt={`Avatar de ${seat.name}`}
                                    className="h-9 w-9 rounded-full object-cover"
                                />
                                <span className="flex-1 font-display text-lg">{seat.name}</span>
                                {seat.playerId === room.hostPlayerId && <Crown size={14} className="text-[#D4AF37]" />}
                                {!seat.connected && <span className="text-xs text-white/30">déconnecté</span>}
                            </div>
                        ))}
                    </div>

                    {room.options && (
                        <div className="mt-4 flex flex-wrap gap-2">
                            {room.options.showHandTotal && <span className="rounded-full border border-white/10 px-3 py-1 text-[10px] uppercase tracking-[0.14em] text-white/45">Total main</span>}
                            {room.options.showGameLog && <span className="rounded-full border border-white/10 px-3 py-1 text-[10px] uppercase tracking-[0.14em] text-white/45">Journal</span>}
                            {room.options.turnTimerSeconds > 0 && <span className="rounded-full border border-white/10 px-3 py-1 text-[10px] uppercase tracking-[0.14em] text-white/45">{room.options.turnTimerSeconds}s / tour</span>}
                        </div>
                    )}

                    {error && <p className="mt-4 text-sm text-red-400">{error}</p>}

                    <div className="mt-8 flex flex-wrap gap-3">
                        {isHost ? (
                            <Button
                                data-testid="lobby-start-game-btn"
                                onClick={startGame}
                                disabled={room.seats.length < 2}
                                className="h-12 bg-[#D4AF37] font-semibold uppercase tracking-[0.18em] text-[#0A0708] hover:bg-[#E5C463]"
                            >
                                <Play size={15} className="mr-2" /> Lancer la partie
                            </Button>
                        ) : (
                            <p className="flex h-12 items-center text-sm text-white/50">En attente que l'hôte lance la partie…</p>
                        )}
                        <Button variant="ghost" data-testid="lobby-quit-btn" onClick={onQuit}>
                            Quitter
                        </Button>
                    </div>
                </motion.div>
            </div>
        );
    }

    // --- Étape 1 : identité (avatar + pseudo) ---
    if (screen === "identity") {
        return (
            <div className="mx-auto max-w-xl px-6 py-16 md:py-24">
                <motion.div initial={{ opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6 }}>
                    <span className="eyebrow-label">Mascarade — Total</span>
                    <h1 className="mt-3 font-display text-5xl font-semibold tracking-tight">Qui es-tu ?</h1>

                    <div className="mt-10 space-y-8 rounded-md border border-[#D4AF37]/15 bg-[#120D0F]/70 p-7">
                        <div>
                            <Label className="eyebrow-label">Avatar</Label>
                            <div className="mt-4">
                                <div className="relative overflow-hidden rounded-xl border border-white/[0.06] bg-[#0A0708]/50 px-10 py-5">
                                    <button
                                        type="button"
                                        aria-label="Avatar précédent"
                                        onClick={() => {
                                            const nextIndex = (avatarIndex - 1 + AVATARS.length) % AVATARS.length;
                                            setAvatarIndex(nextIndex);
                                            setAvatar(AVATARS[nextIndex].src);
                                        }}
                                        className="absolute left-2 top-1/2 z-10 flex h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full border border-white/10 bg-[#120D0F]/90 text-white/60 transition hover:border-[#D4AF37]/50 hover:text-[#D4AF37]"
                                    >
                                        <ChevronLeft size={18} />
                                    </button>

                                    <motion.div
                                        key={avatarIndex}
                                        initial={{ opacity: 0, x: 24, scale: 0.96 }}
                                        animate={{ opacity: 1, x: 0, scale: 1 }}
                                        transition={{ duration: 0.2 }}
                                        className="flex justify-center"
                                    >
                                        <button
                                            type="button"
                                            data-testid={`avatar-${AVATARS[avatarIndex].id}`}
                                            onClick={() => setAvatar(AVATARS[avatarIndex].src)}
                                            className="relative h-28 w-28 overflow-hidden rounded-full border-2 border-[#D4AF37] bg-[#D4AF37]/10 shadow-[0_0_35px_rgba(212,175,55,0.16)]"
                                        >
                                            <img
                                                src={AVATARS[avatarIndex].src}
                                                alt={`Avatar ${AVATARS[avatarIndex].id}`}
                                                className="h-full w-full object-cover"
                                            />
                                        </button>
                                    </motion.div>

                                    <button
                                        type="button"
                                        aria-label="Avatar suivant"
                                        onClick={() => {
                                            const nextIndex = (avatarIndex + 1) % AVATARS.length;
                                            setAvatarIndex(nextIndex);
                                            setAvatar(AVATARS[nextIndex].src);
                                        }}
                                        className="absolute right-2 top-1/2 z-10 flex h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full border border-white/10 bg-[#120D0F]/90 text-white/60 transition hover:border-[#D4AF37]/50 hover:text-[#D4AF37]"
                                    >
                                        <ChevronRight size={18} />
                                    </button>

                                    <div className="mt-3 flex justify-center gap-1.5">
                                        {AVATARS.map((item, index) => (
                                            <button
                                                key={item.id}
                                                type="button"
                                                aria-label={`Choisir l'avatar ${item.id}`}
                                                onClick={() => {
                                                    setAvatarIndex(index);
                                                    setAvatar(item.src);
                                                }}
                                                className={`h-1.5 rounded-full transition-all ${index === avatarIndex ? "w-5 bg-[#D4AF37]" : "w-1.5 bg-white/20 hover:bg-white/40"}`}
                                            />
                                        ))}
                                    </div>
                                </div>
                                <p className="mt-2 text-center text-xs text-white/35">Avatar {avatarIndex + 1} / {AVATARS.length}</p>
                            </div>
                        </div>

                        <div>
                            <Label className="eyebrow-label">Pseudo</Label>
                            <Input
                                data-testid="identity-name-input"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                placeholder="Ton pseudo"
                                maxLength={20}
                                className="mt-3 border-white/10 bg-[#0A0708]/80 text-[#FAF9F6]"
                            />
                        </div>

                        <Button
                            data-testid="identity-continue-btn"
                            onClick={confirmIdentity}
                            disabled={!identityValid}
                            className="h-12 w-full bg-[#D4AF37] font-semibold uppercase tracking-[0.2em] text-[#0A0708] hover:bg-[#E5C463] disabled:opacity-40"
                        >
                            Continuer
                        </Button>
                    </div>
                </motion.div>
            </div>
        );
    }

    // --- Étape 2 : menu (créer / rejoindre / salons publics) ---
    if (screen === "menu") {
        return (
            <div className="mx-auto max-w-xl px-6 py-16 md:py-24">
                <motion.div initial={{ opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6 }}>
                    <span className="eyebrow-label flex items-center gap-2">
                        <img src={avatar} alt={`Avatar de ${name}`} className="h-7 w-7 rounded-full object-cover" />
                        {name}
                    </span>
                    <h1 className="mt-3 font-display text-5xl font-semibold tracking-tight">Total</h1>

                    {error && <p className="mt-4 text-sm text-red-400">{error}</p>}

                    <div className="mt-10 space-y-4">
                        <div className="overflow-hidden rounded-xl border border-[#D4AF37]/15 bg-[#120D0F]/70 backdrop-blur-xl">
                            <div className="border-b border-white/[0.06] px-6 py-5">
                                <p className="flex items-center gap-2 font-display text-2xl">
                                    <Settings2 size={17} className="text-[#D4AF37]" /> Options de la partie
                                </p>
                                <p className="mt-1 text-xs text-white/40">Configure la partie avant de créer le salon.</p>
                            </div>

                            <div className="grid gap-px bg-white/[0.05] sm:grid-cols-2">
                                <div className="bg-[#0A0708]/70 p-5">
                                    <div className="flex items-start justify-between gap-4">
                                        <div>
                                            <p className="flex items-center gap-2 text-sm font-semibold"><Users size={14} className="text-[#D4AF37]" /> Salon public</p>
                                            <p className="mt-1 text-[11px] leading-relaxed text-white/35">Visible dans la liste des salons ouverts.</p>
                                        </div>
                                        <Switch data-testid="create-public-switch" checked={isPublic} onCheckedChange={setIsPublic} />
                                    </div>
                                </div>

                                <div className="bg-[#0A0708]/70 p-5">
                                    <div className="flex items-start justify-between gap-4">
                                        <div>
                                            <p className="flex items-center gap-2 text-sm font-semibold"><Sparkles size={14} className="text-[#D4AF37]" /> Cartes spéciales</p>
                                            <p className="mt-1 text-[11px] leading-relaxed text-white/35">Passe, Positif, Négatif, Échange, Vol…</p>
                                        </div>
                                        <Switch data-testid="create-specials-switch" checked={specialCards} onCheckedChange={setSpecialCards} />
                                    </div>
                                </div>

                                <div className="bg-[#0A0708]/70 p-5">
                                    <div className="flex items-start justify-between gap-4">
                                        <div>
                                            <p className="flex items-center gap-2 text-sm font-semibold"><Eye size={14} className="text-[#D4AF37]" /> Total de la main</p>
                                            <p className="mt-1 text-[11px] leading-relaxed text-white/35">Afficher le calcul de ta main en cours.</p>
                                        </div>
                                        <Switch data-testid="create-hand-total-switch" checked={showHandTotal} onCheckedChange={setShowHandTotal} />
                                    </div>
                                </div>

                                <div className="bg-[#0A0708]/70 p-5">
                                    <div className="flex items-start justify-between gap-4">
                                        <div>
                                            <p className="flex items-center gap-2 text-sm font-semibold"><FileText size={14} className="text-[#D4AF37]" /> Journal de partie</p>
                                            <p className="mt-1 text-[11px] leading-relaxed text-white/35">Afficher l'historique des actions.</p>
                                        </div>
                                        <Switch data-testid="create-game-log-switch" checked={showGameLog} onCheckedChange={setShowGameLog} />
                                    </div>
                                </div>
                            </div>

                            <div className="border-t border-white/[0.06] bg-[#120D0F]/80 p-5">
                                <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                                    <div>
                                        <p className="flex items-center gap-2 text-sm font-semibold"><Clock3 size={14} className="text-[#D4AF37]" /> Chronomètre par tour</p>
                                        <p className="mt-1 text-[11px] leading-relaxed text-white/35">À la fin du temps, le serveur joue automatiquement à ta place.</p>
                                    </div>
                                    <div className="flex flex-wrap gap-1.5" data-testid="turn-timer-options">
                                        {[30, 45, 60, 90].map((seconds) => (
                                            <button
                                                key={seconds}
                                                type="button"
                                                data-testid={`turn-timer-${seconds}`}
                                                onClick={() => setTurnTimerSeconds(seconds)}
                                                className={`rounded-full border px-3 py-1.5 text-[10px] font-semibold uppercase tracking-[0.14em] transition ${turnTimerSeconds === seconds ? "border-[#D4AF37]/60 bg-[#D4AF37]/10 text-[#D4AF37]" : "border-white/10 text-white/40 hover:border-[#D4AF37]/30 hover:text-white/70"}`}
                                            >
                                                {seconds}s
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>

                            <div className="p-5">
                                <Button
                                    data-testid="menu-create-room-btn"
                                    onClick={handleCreate}
                                    className="h-12 w-full bg-[#D4AF37] font-semibold uppercase tracking-[0.18em] text-[#0A0708] hover:bg-[#E5C463]"
                                >
                                    <Play size={15} className="mr-2" /> Créer le salon
                                </Button>
                            </div>
                        </div>

                        <div className="rounded-md border border-[#D4AF37]/15 bg-[#120D0F]/70 p-6">
                            <p className="font-display text-xl">Rejoindre par code</p>
                            <div className="mt-4 flex gap-2">
                                <Input
                                    data-testid="join-code-input"
                                    value={joinCode}
                                    onChange={(e) => setJoinCode(e.target.value.toUpperCase())}
                                    placeholder="ABC123"
                                    maxLength={6}
                                    className="border-white/10 bg-[#0A0708]/80 text-[#FAF9F6]"
                                />
                                <Button
                                    data-testid="menu-join-room-btn"
                                    onClick={() => handleJoin(joinCode)}
                                    disabled={joinCode.trim().length < 4}
                                    className="bg-[#D4AF37] font-semibold text-[#0A0708] hover:bg-[#E5C463] disabled:opacity-40"
                                >
                                    Rejoindre
                                </Button>
                            </div>
                        </div>

                        <button
                            type="button"
                            data-testid="menu-show-public-btn"
                            onClick={() => setScreen("public")}
                            className="w-full rounded-md border border-white/[0.06] bg-[#120D0F]/70 p-6 text-left font-display text-xl hover:border-[#D4AF37]/30"
                        >
                            Rejoindre un salon public →
                        </button>
                    </div>

                    <Button variant="ghost" data-testid="menu-quit-btn" onClick={onQuit} className="mt-6">
                        Retour au catalogue
                    </Button>
                </motion.div>
            </div>
        );
    }

    // --- Étape 3 : liste des salons publics ---
    return (
        <div className="mx-auto max-w-xl px-6 py-16 md:py-24">
            <motion.div initial={{ opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6 }}>
                <div className="flex items-center justify-between">
                    <h1 className="font-display text-4xl font-semibold tracking-tight">Salons publics</h1>
                    <button type="button" data-testid="public-refresh-btn" onClick={refreshPublicRooms} className="text-white/50 hover:text-[#D4AF37]">
                        <RefreshCw size={16} />
                    </button>
                </div>

                {error && <p className="mt-4 text-sm text-red-400">{error}</p>}

                <div className="mt-6 space-y-2">
                    {publicRooms.length === 0 && <p className="text-sm text-white/40">Aucun salon public ouvert pour l'instant.</p>}
                    {publicRooms.map((r) => (
                        <button
                            key={r.code}
                            type="button"
                            data-testid={`public-room-${r.code}`}
                            onClick={() => handleJoin(r.code)}
                            className="flex w-full items-center justify-between rounded-md border border-white/[0.06] bg-[#120D0F]/70 px-5 py-4 text-left hover:border-[#D4AF37]/30"
                        >
                            <div>
                                <p className="font-display text-lg">{r.code}</p>
                                <p className="text-xs text-white/40">Hôte : {r.hostName}</p>
                            </div>
                            <span className="text-xs uppercase tracking-widest text-white/40">{r.playerCount}/8 joueurs</span>
                        </button>
                    ))}
                </div>

                <Button variant="ghost" data-testid="public-back-btn" onClick={() => setScreen("menu")} className="mt-6">
                    ← Retour
                </Button>
            </motion.div>
        </div>
    );
}