import { useEffect, useRef, useState } from "react";
import { motion } from "framer-motion";
import { Play, Lock, Unlock } from "lucide-react";
import Reveal from "@/components/Reveal";
import { GAMES } from "@/data/games";

const RIFT_URL = "https://rift-imposter.preview.emergentagent.com/";

function GameCard({ game, index, onNavigate }) {
    const [expanded, setExpanded] = useState(false);
    const [isTruncated, setIsTruncated] = useState(false);
    const descRef = useRef(null);

    useEffect(() => {
        const el = descRef.current;
        if (!el) return;
        setIsTruncated(el.scrollHeight > el.clientHeight + 1);
    }, [game.desc]);

    return (
        <Reveal delay={0.12 * index} className="h-full">
            <motion.article
                data-testid={`game-card-${game.id}`}
                whileHover={game.live ? { y: -10 } : undefined}
                transition={{ type: "spring", stiffness: 240, damping: 22 }}
                className={`group relative flex h-full flex-col overflow-hidden rounded-md border backdrop-blur-xl ${
                    game.live
                        ? "border-[#D4AF37]/25 bg-[#120D0F]/80 shadow-[0_0_60px_rgba(212,175,55,0.08)]"
                        : "border-white/[0.06] bg-[#120D0F]/60"
                }`}
            >
                <div className="relative aspect-[16/10] overflow-hidden">
                    <img
                        src={game.img}
                        alt={game.live ? `Illustration du jeu ${game.name}` : ""}
                        className={`h-full w-full object-cover transition-transform duration-700 ${
                            game.live
                                ? "group-hover:scale-105"
                                : "opacity-40 grayscale contrast-125"
                        }`}
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-[#120D0F] via-transparent to-transparent" />
                    <div className="absolute left-4 top-4 flex items-center gap-2">
                        {game.live ? (
                            <span
                                data-testid="badge-disponible"
                                className="inline-flex items-center gap-2 rounded-full border border-[#D4AF37]/40 bg-[#0A0708]/60 px-4 py-1.5 text-[10px] font-semibold uppercase tracking-[0.22em] text-[#D4AF37] backdrop-blur-md"
                            >
                                <Unlock size={11} />
                                Disponible
                            </span>
                        ) : (
                            <span
                                data-testid={`badge-a-venir-${game.id}`}
                                className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/5 px-4 py-1.5 text-[10px] font-semibold uppercase tracking-[0.22em] text-white/50"
                            >
                                <Lock size={11} />À venir
                            </span>
                        )}
                    </div>
                    {!game.live && (
                        <div className="absolute inset-0 flex items-center justify-center" aria-hidden="true">
                            <Lock size={34} strokeWidth={1.2} className="text-white/25" />
                        </div>
                    )}
                </div>

                <div className="flex flex-1 flex-col p-7 md:p-8">
                    <h3
                        className={`font-display text-3xl font-semibold tracking-tight ${
                            game.live ? "text-[#FAF9F6]" : "text-[#A19D98]"
                        }`}
                    >
                        {game.name}
                    </h3>
                    <div className="mt-4 flex flex-wrap gap-2">
                        {game.tags.map((tag) => (
                            <span
                                key={tag}
                                className={`rounded-full border px-3 py-1 text-[10px] uppercase tracking-[0.16em] ${
                                    game.live
                                        ? "border-[#D4AF37]/20 text-[#D4AF37]/80"
                                        : "border-white/10 text-white/40"
                                }`}
                            >
                                {tag}
                            </span>
                        ))}
                    </div>
                    <div className="mb-2 mt-4">
                        <p
                            ref={descRef}
                            className={`text-sm leading-relaxed ${game.live ? "text-[#A19D98]" : "text-[#66615D]"} ${
                                expanded ? "" : "line-clamp-3"
                            }`}
                        >
                            {game.desc}
                        </p>
                        {isTruncated && (
                            <button
                                type="button"
                                data-testid={`catalogue-readmore-${game.id}-btn`}
                                onClick={() => setExpanded((v) => !v)}
                                className="mt-1.5 text-[11px] font-semibold uppercase tracking-[0.14em] text-[#D4AF37]/80 hover:text-[#D4AF37]"
                            >
                                {expanded ? "Lire moins" : "Lire plus"}
                            </button>
                        )}
                    </div>
                    {game.live && game.route ? (
                        // Bouton interne (Total)
                        <button
                            type="button"
                            data-testid={`catalogue-play-${game.id}-btn`}
                            onClick={() => onNavigate(game.route)}
                            className="mt-auto inline-flex w-fit items-center gap-3 rounded-full bg-[#D4AF37] px-7 py-3.5 text-[12px] font-semibold uppercase tracking-[0.18em] text-[#0A0708] transition-colors duration-300 hover:bg-[#F3E5AB]"
                        >
                            Jouer maintenant
                            <Play size={13} fill="currentColor" />
                        </button>
                    ) : game.live ? (
                        // Lien externe (Rift Imposter)
                        <a
                            data-testid="catalogue-play-rift-btn"
                            href={RIFT_URL}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="mt-auto inline-flex w-fit items-center gap-3 rounded-full bg-[#D4AF37] px-7 py-3.5 text-[12px] font-semibold uppercase tracking-[0.18em] text-[#0A0708] transition-colors duration-300 hover:bg-[#F3E5AB]"
                        >
                            Jouer maintenant
                            <Play size={13} fill="currentColor" />
                        </a>
                    ) : (
                        // Texte placeholder (jeux non disponibles)
                        <span className="font-display mt-auto text-sm italic text-[#66615D]">
                            Le sceau se brisera bientôt…
                        </span>
                    )}
                </div>
            </motion.article>
        </Reveal>
    );
}

export default function Catalogue({ onNavigate }) {
    return (
        <div data-testid="page-catalogue" className="relative overflow-hidden">
            <div className="glow-orb right-[-8%] top-[8%] h-[400px] w-[400px] bg-[#4A1525]/60" aria-hidden="true" />

            <section className="relative z-10 min-h-screen px-8 py-32 md:px-16 lg:px-24">
                <Reveal>
                    <p className="eyebrow-label" data-testid="catalogue-eyebrow">
                        La table de jeu
                    </p>
                    <h2
                        data-testid="catalogue-title"
                        className="font-display mt-4 text-5xl font-semibold leading-[1.05] tracking-tight md:text-6xl"
                    >
                        Le <span className="italic text-[#D4AF37]">catalogue</span>
                    </h2>
                    <p className="mt-6 max-w-xl text-base leading-relaxed text-[#A19D98]">
                        Un jeu est ouvert aujourd'hui. D'autres masques attendent leur tour.
                    </p>
                </Reveal>

                <div className="mt-16 grid grid-cols-1 gap-8 md:grid-cols-2 lg:grid-cols-3">
                    {GAMES.map((game, i) => (
                        <GameCard key={game.id} game={game} index={i} onNavigate={onNavigate} />
                    ))}
                </div>
            </section>
        </div>
    );
}
