import useNetworkOneUpRoom from "./room/useNetworkOneUpRoom";
import OneUpLobby from "./OneUpLobby";
import OneUpBoard from "./OneUpBoard";

export default function OneUpGame({ onNavigate }) {
    const roomApi = useNetworkOneUpRoom();

    if (roomApi.connectError) {
        return (
            <div className="flex min-h-screen items-center justify-center bg-[#05070A] px-6 text-center">
                <p className="text-[#FF2E92]">{roomApi.connectError}</p>
            </div>
        );
    }

    if (!roomApi.room || roomApi.room.phase === "lobby") {
        return (
            <OneUpLobby
                room={roomApi.room}
                isHost={roomApi.isHost}
                createRoom={roomApi.createRoom}
                joinRoom={roomApi.joinRoom}
                listPublicRooms={roomApi.listPublicRooms}
                startGame={roomApi.startGame}
                onQuit={() => {
                    roomApi.leaveRoom();
                    onNavigate("catalogue");
                }}
            />
        );
    }

    return (
        <OneUpBoard
            view={roomApi.view}
            answer={roomApi.answer}
            onQuit={() => {
                roomApi.leaveRoom();
                onNavigate("catalogue");
            }}
        />
    );
}
