/* ------------------------------------------------------------------ */
/* RNG déterministe (mulberry32) — l'état vit dans l'état de partie,   */
/* ce qui permettra au serveur de rejouer/valider une partie.          */
/* ------------------------------------------------------------------ */

export function nextRandom(seedState) {
    let t = (seedState + 0x6d2b79f5) >>> 0;
    let x = t;
    x = Math.imul(x ^ (x >>> 15), x | 1);
    x ^= x + Math.imul(x ^ (x >>> 7), x | 61);
    const value = ((x ^ (x >>> 14)) >>> 0) / 4294967296;
    return { seedState: t, value };
}

export function shuffle(cards, seedState) {
    const out = [...cards];
    let seed = seedState;
    for (let i = out.length - 1; i > 0; i -= 1) {
        const r = nextRandom(seed);
        seed = r.seedState;
        const j = Math.floor(r.value * (i + 1));
        [out[i], out[j]] = [out[j], out[i]];
    }
    return { cards: out, seedState: seed };
}

let cardCounter = 0;
function makeId(prefix) {
    cardCounter += 1;
    return `${prefix}-${cardCounter}`;
}

export function makeNumberCard(value) {
    return { id: makeId("n"), kind: "number", value };
}

export function makeSpecialCard(special) {
    return { id: makeId("s"), kind: "special", special };
}

/** Construit le paquet complet : 95 numériques (+ 25 spéciales si activées). */
export function buildDeck({ specialCards = false } = {}) {
    const deck = [];
    NUMBER_VALUES.forEach((value) => {
        for (let i = 0; i < COPIES_PER_VALUE; i += 1) deck.push(makeNumberCard(value));
    });
    if (specialCards) {
        SPECIAL_DECK.forEach(({ special, count }) => {
            for (let i = 0; i < count; i += 1) deck.push(makeSpecialCard(special));
        });
    }
    return deck;
}

export function isNumberCard(card) {
    return Boolean(card) && card.kind === "number";
}

export function cardLabel(card) {
    if (!card) return "";
    if (isNumberCard(card)) return card.value > 0 ? `+${card.value}` : `${card.value}`;
    return SPECIAL_INFO[card.special]?.short ?? card.special;
}

export function formatTotal(value) {
    return value > 0 ? `+${value}` : `${value}`;
}
