import { useCallback, useEffect, useRef, useState } from "react";
import { io } from "socket.io-client";

const SERVER_URL = process.env.REACT_APP_MASCARADE_SERVER_URL;
const SESSION_KEY = "mascarade-total-session";

function loadSession() {
    try {
        return JSON.parse(localStorage.getItem(SESSION_KEY)) || null;
    } catch {
        return null;
    }
}

function saveSession(session) {
    localStorage.setItem(SESSION_KEY, JSON.stringify(session));
}

function clearSession() {
    localStorage.removeItem(SESSION_KEY);
}

export default function useNetworkTotalRoom() {
    const socketRef = useRef(null);
    const [room, setRoom] = useState(null);
    const [myPlayerId, setMyPlayerId] = useState(null);
    const [connectError, setConnectError] = useState(null);

    useEffect(() => {
        const session = loadSession();
        const socket = io(SERVER_URL, {
            transports: ["websocket"],
            auth: session?.sessionToken ? { reconnectToken: session.sessionToken } : {},
            reconnection: true,
            reconnectionAttempts: Infinity,
        });
        socketRef.current = socket;

        socket.on("connect", () => setConnectError(null));
        socket.on("connect_error", () => setConnectError("Connexion au serveur impossible."));
        socket.on("room:update", (nextRoom) => {
            setRoom(nextRoom);
            if (nextRoom?.phase !== "lobby" && session?.playerId) setMyPlayerId(session.playerId);
        });
        socket.on("session:restored", ({ code, playerId }) => {
            const current = loadSession();
            if (current?.sessionToken) {
                saveSession({ ...current, code, playerId });
                setMyPlayerId(playerId);
            }
        });

        return () => socket.disconnect();
    }, []);

    const createRoom = useCallback(({ name, avatar, isPublic, specialCards, showHandTotal, showGameLog, turnTimerSeconds }) => {
        return new Promise((resolve) => {
            socketRef.current.emit("lobby:create", { name, avatar, isPublic, specialCards, showHandTotal, showGameLog, turnTimerSeconds }, (res) => {
                if (res.ok) {
                    setMyPlayerId(res.playerId);
                    saveSession({ code: res.code, playerId: res.playerId, sessionToken: res.sessionToken });
                }
                resolve(res);
            });
        });
    }, []);

    const joinRoom = useCallback(({ code, name, avatar }) => {
        return new Promise((resolve) => {
            socketRef.current.emit("lobby:join", { code, name, avatar }, (res) => {
                if (res.ok) {
                    setMyPlayerId(res.playerId);
                    saveSession({ code: res.code, playerId: res.playerId, sessionToken: res.sessionToken });
                }
                resolve(res);
            });
        });
    }, []);

    const listPublicRooms = useCallback(() => {
        return new Promise((resolve) => {
            socketRef.current.emit("lobby:list-public", {}, (res) => resolve(res.rooms ?? []));
        });
    }, []);

    const startGame = useCallback(() => {
        socketRef.current.emit("lobby:start", {});
    }, []);

    const send = useCallback((action) => {
        socketRef.current.emit("game:action", action);
    }, []);

    const leaveRoom = useCallback(() => {
        const socket = socketRef.current;
        clearSession();
        setRoom(null);
        setMyPlayerId(null);
        if (!socket) return;
        socket.emit("lobby:leave", {}, () => socket.disconnect());
    }, []);

    const isHost = Boolean(room && myPlayerId && room.hostPlayerId === myPlayerId);

    return {
        room,
        view: room?.view ?? null,
        myPlayerId,
        isHost,
        connectError,
        createRoom,
        joinRoom,
        listPublicRooms,
        startGame,
        send,
        leaveRoom,
    };
}
