import { useEffect, useState } from "react";
import Lenis from "lenis";
import { AnimatePresence, motion } from "framer-motion";
import "@/App.css";
import Sidebar from "@/components/Sidebar";
import Home from "@/pages/Home";
import HowToPlay from "@/pages/HowToPlay";
import Catalogue from "@/pages/Catalogue";
import Total from "@/pages/Total";
import OneUp from "@/pages/OneUp";

const PAGES = {
    accueil: Home,
    comment: HowToPlay,
    catalogue: Catalogue,
    total: Total,
    "1up": OneUp,
};

function App() {
    const [page, setPage] = useState("accueil");
    const [sidebarOpen, setSidebarOpen] = useState(true);
    const isFullBleed = page === "total" || page === "1up";

    // La sidebar se replie automatiquement en entrant sur une page plein écran,
    // et se rouvre automatiquement dès qu'on la quitte.
    useEffect(() => {
        setSidebarOpen(!isFullBleed);
    }, [isFullBleed]);

    useEffect(() => {
        const lenis = new Lenis({ lerp: 0.09, wheelMultiplier: 1 });
        let rafId;

        const loop = (time) => {
            lenis.raf(time);
            rafId = requestAnimationFrame(loop);
        };

        rafId = requestAnimationFrame(loop);

        return () => {
            cancelAnimationFrame(rafId);
            lenis.destroy();
        };
    }, []);

    useEffect(() => {
        window.scrollTo(0, 0);
    }, [page]);

    const Page = PAGES[page];

    return (
        <div className="min-h-screen bg-[#0A0708] text-[#FAF9F6]">
            <div className="grain-overlay" aria-hidden="true" />

            <Sidebar
                active={page}
                onNavigate={setPage}
                open={sidebarOpen}
                onToggle={() => setSidebarOpen((v) => !v)}
                overlay={isFullBleed}
            />

            <main className={isFullBleed ? "" : "ml-16 md:ml-64"}>
                <AnimatePresence mode="wait">
                    <motion.div
                        key={page}
                        initial={{ opacity: 0, y: 28, filter: "blur(8px)" }}
                        animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
                        exit={{ opacity: 0, y: -20, filter: "blur(8px)" }}
                        transition={{ duration: 0.55, ease: [0.22, 1, 0.36, 1] }}
                    >
                        <Page onNavigate={setPage} />
                    </motion.div>
                </AnimatePresence>
            </main>
        </div>
    );
}

export default App;