import { motion } from "framer-motion";
import { cardLabel, isNumberCard, SPECIAL_INFO } from "../engine/cards";

export default function PlayingCard({
    card,
    faceDown = false,
    selected = false,
    disabled = false,
    dimmed = false,
    onClick,
    testId,
    size = "md",
    layoutId,
    draggableProps = {},
}) {
    const sizes = {
        sm: "h-20 w-14 text-lg",
        md: "h-28 w-20 text-2xl",
        lg: "h-36 w-24 text-3xl",
    };

    if (faceDown) {
        return (
            <motion.div
                layout
                data-testid={testId}
                onClick={disabled ? undefined : onClick}
                whileHover={!disabled && onClick ? { y: -5, scale: 1.03 } : undefined}
                whileTap={!disabled && onClick ? { scale: 0.97 } : undefined}
                transition={{ type: "spring", stiffness: 320, damping: 25 }}
                className={`relative flex ${sizes[size]} shrink-0 items-center justify-center overflow-hidden rounded-lg border border-[#D4AF37]/25 bg-[#2D0A14] shadow-[inset_0_0_24px_rgba(212,175,55,0.04)] ${
                    onClick && !disabled ? "cursor-pointer hover:border-[#D4AF37]/70" : ""
                } ${selected ? "ring-2 ring-[#D4AF37]" : ""}`}
            >
                <span className="absolute inset-1 rounded-md border border-[#D4AF37]/10" />
                <span className="font-display text-xl text-[#D4AF37]/70">M</span>
            </motion.div>
        );
    }

    const number = isNumberCard(card);
    const positive = number && card.value > 0;
    const negative = number && card.value < 0;

    return (
        <motion.div
            layout
            layoutId={layoutId}
            data-testid={testId}
            onClick={disabled ? undefined : onClick}
            whileHover={!disabled && onClick ? { y: -9, rotate: -1.5, scale: 1.035 } : { y: 0 }}
            whileTap={!disabled && onClick ? { scale: 0.97, y: -3 } : undefined}
            transition={{ layout: { type: "spring", stiffness: 420, damping: 30 }, type: "spring", stiffness: 300, damping: 22 }}
            {...draggableProps}
            className={`group relative flex ${sizes[size]} shrink-0 select-none flex-col items-center justify-center overflow-hidden rounded-lg border bg-[#120D0F] font-display font-semibold shadow-[0_8px_20px_rgba(0,0,0,0.2)] transition-[box-shadow,border-color,opacity] duration-300 ${
                number
                    ? positive
                        ? "border-[#D4AF37]/45 text-[#F2D57E]"
                        : negative
                          ? "border-[#8C2F3C]/65 text-[#E58C97]"
                          : "border-white/15 text-white/70"
                    : "border-[#5B7CB8]/55 text-[#9DBBEA]"
            } ${selected ? "ring-2 ring-[#D4AF37] shadow-[0_0_34px_rgba(212,175,55,0.38)]" : ""} ${dimmed ? "opacity-30" : ""} ${disabled ? "cursor-not-allowed" : onClick ? "cursor-pointer" : ""}`}
        >
            <span className={`pointer-events-none absolute inset-x-2 top-2 h-px opacity-40 ${number ? (positive ? "bg-[#D4AF37]" : negative ? "bg-[#8C2F3C]" : "bg-white/30") : "bg-[#5B7CB8]"}`} />
            <span className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_50%_0%,rgba(255,255,255,0.07),transparent_48%)] opacity-70" />
            {number ? (
                <span className="relative">{cardLabel(card)}</span>
            ) : (
                <span className="relative px-1 text-center text-[11px] font-semibold uppercase leading-tight tracking-[0.12em]">
                    {SPECIAL_INFO[card.special]?.label}
                </span>
            )}
            {!number && (
                <span className="relative mt-1 text-[9px] uppercase tracking-[0.2em] text-white/35">Spéciale</span>
            )}
        </motion.div>
    );
}
