import { useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, LayoutGroup, motion } from "framer-motion";
import { Clock3, Gavel, History, LogOut, RotateCcw, Sparkles, Target } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import Hand from "./components/Hand";
import Market from "./components/Market";
import PlayersBar from "./components/PlayersBar";
import PlayingCard from "./components/PlayingCard";
import RulesPanel from "./components/RulesPanel";
import { SPECIAL, SPECIAL_INFO, formatTotal, isNumberCard } from "./engine/cards";
import { CONSTRAINT_LABEL, canDeclareTotal, computeExpression } from "./engine/rules";

export default function TotalTable({ view, send, onQuit, onRestart }) {
    const [dialog, setDialog] = useState(null); // 'total' | 'counter' | 'play-special'
    const [counterTarget, setCounterTarget] = useState(null);
    const [specialCard, setSpecialCard] = useState(null);
    const [flow, setFlow] = useState({ targetId: null, ownCardId: null, targetCardIndex: null });
    const [now, setNow] = useState(Date.now());

    const { me, pending, phase, currentPlayerId } = view;
    const isMyTurn = me?.id === currentPlayerId;
    const finished = phase === "finished";
    const currentPlayer = view.players.find((player) => player.id === currentPlayerId) ?? null;
    const introActive = Boolean(view.introUntil && now < view.introUntil);
    const secondsLeft = view.turnDeadline ? Math.max(0, Math.ceil((view.turnDeadline - now) / 1000)) : null;
    const timerUrgent = secondsLeft !== null && secondsLeft <= 10;

    useEffect(() => {
        setDialog(null);
        setCounterTarget(null);
        setSpecialCard(null);
        setFlow({ targetId: null, ownCardId: null, targetCardIndex: null });
    }, [currentPlayerId]);

    useEffect(() => {
        const timer = window.setInterval(() => setNow(Date.now()), 250);
        return () => window.clearInterval(timer);
    }, []);

    const opponents = useMemo(
        () => view.players.filter((p) => p.id !== me?.id),
        [view.players, me?.id],
    );
    const expression = useMemo(() => computeExpression(me?.hand ?? []), [me?.hand]);
    const declinedCount = view.players.filter((p) => p.declinedThisCycle).length;

    const awaitingDiscard = pending && ["discard", "vol_discard"].includes(pending.kind);
    const resolvingSpecial = isMyTurn && pending?.kind === "special";
    const isTakingCard = pending?.kind === "discard" && pending?.reason === "take";
    const canAct = isMyTurn && !pending && !finished;

    const handleHandClick = (card) => {
        if (finished) return;
        if (awaitingDiscard) {
            if (pending?.kind === "discard" && pending?.takenCardId === card.id) return;
            send({ type: "DISCARD", playerId: me.id, cardId: card.id });
            return;
        }
        if (resolvingSpecial && pending.special === SPECIAL.ECHANGE) {
            setFlow((f) => ({ ...f, ownCardId: card.id }));
            return;
        }
        if (canAct && !isNumberCard(card)) {
            setSpecialCard(card);
            setDialog("play-special");
        }
    };

    return (
        <div className="mx-auto max-w-6xl px-5 pb-24 pt-10 md:px-8">
            {/* Bandeau de partie */}
            <header className="mb-7 flex flex-wrap items-end justify-between gap-4">
                <div>
                    <span className="eyebrow-label">
                        Room {view.roomId} — Total — cycle {view.cycle}
                    </span>
                    <h1 className="mt-2 font-display text-4xl font-semibold tracking-tight md:text-5xl">
                        Table de Total
                    </h1>
                </div>
                <div className="flex flex-wrap items-center gap-3 text-[11px] uppercase tracking-[0.16em] text-white/45">
                    {secondsLeft !== null && !finished && (
                        <div
                            data-testid="turn-timer"
                            className={`flex items-center gap-2 rounded-full border px-3 py-1.5 font-mono text-[12px] normal-case tracking-normal transition ${
                                isMyTurn
                                    ? timerUrgent
                                        ? "border-[#8C2F3C]/70 bg-[#2D0A14]/60 text-[#E58C97]"
                                        : "border-[#D4AF37]/35 bg-[#D4AF37]/8 text-[#F2D57E]"
                                    : "border-white/10 bg-white/[0.02] text-white/35"
                            }`}
                        >
                            <Clock3 size={13} />
                            {isMyTurn ? `${secondsLeft}s` : `Tour de ${currentPlayer?.name ?? "…"} · ${secondsLeft}s`}
                        </div>
                    )}
                    <span data-testid="deck-count">Pioche {view.deckCount}</span>
                    <span data-testid="discard-count">Corbeille {view.discardCount}</span>
                    <Button
                        variant="ghost"
                        size="sm"
                        data-testid="quit-game-button"
                        onClick={onQuit}
                        className="text-white/50 hover:text-[#D4AF37]"
                    >
                        <LogOut size={13} className="mr-1.5" /> Quitter
                    </Button>
                </div>
            </header>

            <PlayersBar
                players={view.players}
                currentPlayerId={currentPlayerId}
                winnerId={view.winnerId}
            />

            <LayoutGroup id="total-board">
            <div className="mt-7 grid gap-7 lg:grid-cols-[1.6fr_1fr]">
                <div className="space-y-7">
                    <Market
                        cards={view.market}
                        canTake={canAct}
                        constraint={me?.constraint}
                        onTake={(card) => send({ type: "TAKE_MARKET", playerId: me.id, cardId: card.id })}
                        declinedCount={declinedCount}
                        playerCount={view.players.length}
                    />

                    {/* Ma zone */}
                    <section
                        data-testid="my-zone"
                        className="rounded-md border border-[#D4AF37]/20 bg-[#150E10]/80 p-6 backdrop-blur-xl"
                    >
                        <>
                                <div className="mb-5 flex flex-wrap items-center justify-between gap-4">
                                    <div>
                                        <span className="eyebrow-label">{me?.name} — mon total</span>
                                        <p
                                            data-testid="my-total-card"
                                            className="font-display text-5xl font-semibold text-[#D4AF37]"
                                        >
                                            {formatTotal(me?.totalCard ?? 0)}
                                        </p>
                                    </div>
                                    {view.options.showHandTotal && (
                                        <div className="text-right text-xs text-white/50">
                                            <p data-testid="my-hand-result">
                                                Ma main (gauche → droite) ={" "}
                                                <span className="font-semibold text-[#FAF9F6]">
                                                    {expression.result}
                                                </span>
                                            </p>
                                            <p className="mt-1 font-mono text-[11px] text-white/35">
                                                {expression.expression}
                                            </p>
                                        </div>
                                    )}
                                </div>

                                {me?.constraint && (
                                    <p className="mb-4 rounded border border-[#8C2F3C]/50 bg-[#2D0A14]/60 px-3 py-2 text-xs text-[#E58C97]">
                                        {CONSTRAINT_LABEL[me.constraint]}
                                    </p>
                                )}

                                {awaitingDiscard && (
                                    <div className="mb-4 rounded border border-[#D4AF37]/40 bg-[#D4AF37]/10 px-3 py-2 text-xs text-[#F2D57E]">
                                        <p data-testid="discard-instruction">
                                            {pending?.kind === "vol_discard"
                                                ? "Choisis une carte à défausser pour terminer le Vol."
                                                : "Choisis une carte à déposer au marché pour terminer ton échange. La carte que tu viens de prendre est verrouillée."}
                                        </p>
                                        {isTakingCard && (
                                            <Button
                                                variant="ghost"
                                                size="sm"
                                                data-testid="cancel-take-button"
                                                onClick={() => send({ type: "CANCEL_TAKE", playerId: me.id })}
                                                className="mt-2 h-8 px-3 text-[#F2D57E] hover:bg-[#D4AF37]/10 hover:text-[#FAF9F6]"
                                            >
                                                Annuler la prise et choisir une autre carte
                                            </Button>
                                        )}
                                    </div>
                                )}

                                <Hand
                                    cards={me?.hand ?? []}
                                    onReorder={(ids) => send({ type: "REORDER_HAND", playerId: me.id, ids })}
                                    onCardClick={handleHandClick}
                                    selectedId={flow.ownCardId}
                                    lockedCardId={isTakingCard ? pending.takenCardId : null}
                                />

                                {view.options.specialCards && (
                                    <p className="mt-4 text-[11px] text-white/35">
                                        <Sparkles size={11} className="mr-1 inline" />
                                        Cliquez une carte spéciale de votre main pour l'utiliser.
                                    </p>
                                )}

                                <div className="mt-6 flex flex-wrap gap-3">
                                    <Button
                                        data-testid="declare-total-button"
                                        disabled={!canAct || !canDeclareTotal(me?.hand ?? [])}
                                        onClick={() => setDialog("total")}
                                        className="bg-[#D4AF37] font-semibold uppercase tracking-[0.18em] text-[#0A0708] hover:bg-[#E5C463] disabled:opacity-35"
                                    >
                                        <Target size={14} className="mr-2" /> Total
                                    </Button>
                                    <Button
                                        variant="outline"
                                        data-testid="counter-total-button"
                                        disabled={!canAct || me?.tookThisCycle || opponents.length === 0}
                                        onClick={() => {
                                            setCounterTarget(null);
                                            setDialog("counter");
                                        }}
                                        className="border-[#8C2F3C]/60 font-semibold uppercase tracking-[0.18em] text-[#E58C97] hover:bg-[#2D0A14]/60 disabled:opacity-35"
                                    >
                                        <Gavel size={14} className="mr-2" /> Contre-Total
                                    </Button>
                                </div>

                                {me?.tookThisCycle && (
                                    <p
                                        data-testid="counter-total-locked"
                                        className="mt-3 text-[11px] text-white/40"
                                    >
                                        Contre-Total indisponible : vous avez pris une carte pendant
                                        le cycle actif.
                                    </p>
                                )}
                        </>
                    </section>
                </div>

                {/* Journal + règles */}
                <aside className="h-fit space-y-5">
                    <RulesPanel />
                    {view.options.showGameLog && (
                        <div
                            data-testid="game-log"
                            className="overflow-hidden rounded-xl border border-white/[0.07] bg-[#120D0F]/60 backdrop-blur-xl"
                        >
                            <div className="flex items-center justify-between border-b border-white/[0.06] px-5 py-4">
                                <span className="eyebrow-label flex items-center gap-2"><History size={12} /> Journal de partie</span>
                                <span className="text-[9px] uppercase tracking-[0.18em] text-white/25">{view.log.length} événements</span>
                            </div>
                            <ul className="max-h-[420px] space-y-1 overflow-y-auto p-3">
                                {view.log.length === 0 && (
                                    <li className="px-2 py-5 text-center text-xs text-white/30">Aucune action pour le moment.</li>
                                )}
                                {view.log.map((entry, index) => (
                                    <li key={entry.id} className={`relative flex gap-3 rounded-lg px-3 py-2.5 ${index === 0 ? "bg-white/[0.035]" : ""}`}>
                                        <span className={`mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full ${index === 0 ? "bg-[#D4AF37] shadow-[0_0_10px_rgba(212,175,55,0.55)]" : "bg-white/15"}`} />
                                        <span className={`text-xs leading-relaxed ${index === 0 ? "text-white/75" : "text-white/45"}`}>{entry.text}</span>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}
                </aside>
            </div>
            </LayoutGroup>

            {/* --- Dialog : confirmation TOTAL --- */}
            <Dialog open={dialog === "total"} onOpenChange={(open) => !open && setDialog(null)}>
                <DialogContent className="border-[#D4AF37]/25 bg-[#120D0F] text-[#FAF9F6]">
                    <DialogHeader>
                        <DialogTitle className="font-display text-3xl">Annoncer TOTAL</DialogTitle>
                        <DialogDescription className="text-white/50">
                            Le calcul se fait strictement de gauche à droite, dans l'ordre affiché.
                        </DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4">
                        <div className="flex flex-wrap gap-2">
                            {(me?.hand ?? []).map((card, index) => (
                                <PlayingCard key={card.id} card={card} size="sm" testId={`total-preview-${index}`} />
                            ))}
                        </div>
                        <p className="font-mono text-sm text-white/70" data-testid="total-preview-expression">
                            {expression.expression}
                        </p>
                        <p className="text-sm">
                            Résultat :{" "}
                            <span data-testid="total-preview-result" className="font-semibold text-[#D4AF37]">
                                {expression.result}
                            </span>
                            {"  •  "}
                            Total recherché :{" "}
                            <span className="font-semibold text-[#D4AF37]">
                                {formatTotal(me?.totalCard ?? 0)}
                            </span>
                        </p>
                        <p className="text-[11px] text-white/35">
                            Le résultat est vérifié par le moteur de jeu, pas par l'affichage.
                        </p>
                    </div>
                    <DialogFooter>
                        <Button variant="ghost" data-testid="total-cancel-button" onClick={() => setDialog(null)}>
                            Annuler
                        </Button>
                        <Button
                            data-testid="total-confirm-button"
                            onClick={() => {
                                setDialog(null);
                                send({
                                    type: "DECLARE_TOTAL",
                                    playerId: me.id,
                                    order: (me?.hand ?? []).map((c) => c.id),
                                });
                            }}
                            className="bg-[#D4AF37] font-semibold uppercase tracking-[0.18em] text-[#0A0708] hover:bg-[#E5C463]"
                        >
                            Confirmer Total
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* --- Dialog : Contre-Total --- */}
            <Dialog open={dialog === "counter"} onOpenChange={(open) => !open && setDialog(null)}>
                <DialogContent className="border-[#8C2F3C]/40 bg-[#120D0F] text-[#FAF9F6]">
                    <DialogHeader>
                        <DialogTitle className="font-display text-3xl">Contre-Total</DialogTitle>
                        <DialogDescription className="text-white/50">
                            Accusez un joueur de posséder déjà son Total. Si vous avez tort, vous
                            perdez vos 5 cartes.
                        </DialogDescription>
                    </DialogHeader>
                    <div className="flex flex-wrap gap-2">
                        {opponents.map((player) => (
                            <button
                                key={player.id}
                                type="button"
                                data-testid={`counter-target-${player.id}`}
                                onClick={() => setCounterTarget(player.id)}
                                className={`rounded-md border px-4 py-2 text-sm transition-colors duration-200 ${
                                    counterTarget === player.id
                                        ? "border-[#E58C97] bg-[#2D0A14]/70 text-[#E58C97]"
                                        : "border-white/10 text-white/60 hover:border-[#8C2F3C]/60"
                                }`}
                            >
                                {player.name}
                            </button>
                        ))}
                    </div>
                    {counterTarget && (
                        <p className="text-sm text-white/70" data-testid="counter-confirm-text">
                            Êtes-vous certain de penser que{" "}
                            {opponents.find((p) => p.id === counterTarget)?.name} possède actuellement
                            son Total ?
                        </p>
                    )}
                    <DialogFooter>
                        <Button variant="ghost" data-testid="counter-cancel-button" onClick={() => setDialog(null)}>
                            Annuler
                        </Button>
                        <Button
                            data-testid="counter-confirm-button"
                            disabled={!counterTarget}
                            onClick={() => {
                                setDialog(null);
                                send({ type: "COUNTER_TOTAL", playerId: me.id, targetId: counterTarget });
                            }}
                            className="bg-[#8C2F3C] font-semibold uppercase tracking-[0.18em] text-[#FAF9F6] hover:bg-[#A33A48] disabled:opacity-35"
                        >
                            Contre-Total
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* --- Dialog : confirmer l'usage d'une carte spéciale --- */}
            <Dialog open={dialog === "play-special"} onOpenChange={(open) => !open && setDialog(null)}>
                <DialogContent className="border-[#5B7CB8]/40 bg-[#120D0F] text-[#FAF9F6]">
                    <DialogHeader>
                        <DialogTitle className="font-display text-3xl">
                            {specialCard ? SPECIAL_INFO[specialCard.special]?.label : ""}
                        </DialogTitle>
                        <DialogDescription className="text-white/55">
                            {specialCard ? SPECIAL_INFO[specialCard.special]?.desc : ""}
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter>
                        <Button variant="ghost" data-testid="special-cancel-button" onClick={() => setDialog(null)}>
                            Annuler
                        </Button>
                        <Button
                            data-testid="special-play-button"
                            onClick={() => {
                                setDialog(null);
                                send({ type: "PLAY_SPECIAL", playerId: me.id, cardId: specialCard.id });
                            }}
                            className="bg-[#5B7CB8] font-semibold uppercase tracking-[0.18em] text-[#0A0708] hover:bg-[#7B99CE]"
                        >
                            Utiliser
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* --- Dialog : résolution d'une carte spéciale --- */}
            <Dialog open={Boolean(resolvingSpecial && isMyTurn)}>
                <DialogContent
                    showCloseButton={false}
                    className="border-[#5B7CB8]/40 bg-[#120D0F] text-[#FAF9F6]"
                >
                    <DialogHeader>
                        <DialogTitle className="font-display text-3xl">
                            {resolvingSpecial ? SPECIAL_INFO[pending.special]?.label : ""}
                        </DialogTitle>
                        <DialogDescription className="text-white/55">
                            {resolvingSpecial ? SPECIAL_INFO[pending.special]?.desc : ""}
                        </DialogDescription>
                    </DialogHeader>

                    <div className="space-y-5">
                        <div>
                            <span className="eyebrow-label">1. Joueur ciblé</span>
                            <div className="mt-3 flex flex-wrap gap-2">
                                {opponents.map((player) => (
                                    <button
                                        key={player.id}
                                        type="button"
                                        data-testid={`special-target-${player.id}`}
                                        onClick={() =>
                                            setFlow({ targetId: player.id, ownCardId: null, targetCardIndex: null })
                                        }
                                        className={`rounded-md border px-4 py-2 text-sm transition-colors duration-200 ${
                                            flow.targetId === player.id
                                                ? "border-[#5B7CB8] bg-[#5B7CB8]/15 text-[#9DBBEA]"
                                                : "border-white/10 text-white/60 hover:border-[#5B7CB8]/60"
                                        }`}
                                    >
                                        {player.name}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {resolvingSpecial && pending.special === SPECIAL.ECHANGE && (
                            <div>
                                <span className="eyebrow-label">2. Ma carte (cliquez dans ma main)</span>
                                <p className="mt-2 text-xs text-white/45">
                                    {flow.ownCardId ? "Carte sélectionnée." : "Aucune carte sélectionnée."}
                                </p>
                            </div>
                        )}

                        {resolvingSpecial &&
                            [SPECIAL.ECHANGE, SPECIAL.VOL].includes(pending.special) &&
                            flow.targetId && (
                                <div>
                                    <span className="eyebrow-label">
                                        {pending.special === SPECIAL.ECHANGE ? "3." : "2."} Carte de
                                        l'adversaire (face cachée)
                                    </span>
                                    <div className="mt-3 flex flex-wrap gap-2">
                                        {Array.from(
                                            {
                                                length:
                                                    opponents.find((p) => p.id === flow.targetId)?.handCount ?? 0,
                                            },
                                            (_, index) => (
                                                <PlayingCard
                                                    key={index}
                                                    faceDown
                                                    size="sm"
                                                    testId={`opponent-card-${index}`}
                                                    selected={flow.targetCardIndex === index}
                                                    onClick={() =>
                                                        setFlow((f) => ({ ...f, targetCardIndex: index }))
                                                    }
                                                />
                                            ),
                                        )}
                                    </div>
                                </div>
                            )}
                    </div>

                    <DialogFooter>
                        <Button
                            variant="ghost"
                            data-testid="special-resolve-cancel-button"
                            onClick={() => send({ type: "CANCEL_PENDING", playerId: me.id })}
                        >
                            Ne pas utiliser l'effet
                        </Button>
                        <Button
                            data-testid="special-resolve-button"
                            disabled={
                                !flow.targetId ||
                                (resolvingSpecial &&
                                    pending.special === SPECIAL.VOL &&
                                    flow.targetCardIndex === null) ||
                                (resolvingSpecial &&
                                    pending.special === SPECIAL.ECHANGE &&
                                    (flow.targetCardIndex === null || !flow.ownCardId))
                            }
                            onClick={() =>
                                send({
                                    type: "RESOLVE_SPECIAL",
                                    playerId: me.id,
                                    targetPlayerId: flow.targetId,
                                    ownCardId: flow.ownCardId,
                                    targetCardIndex: flow.targetCardIndex,
                                })
                            }
                            className="bg-[#5B7CB8] font-semibold uppercase tracking-[0.18em] text-[#0A0708] hover:bg-[#7B99CE] disabled:opacity-35"
                        >
                            Valider
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* --- Dialog : Voir Total (information privée) --- */}
            <Dialog open={Boolean(view.reveal)}>
                <DialogContent
                    showCloseButton={false}
                    className="border-[#D4AF37]/30 bg-[#120D0F] text-[#FAF9F6]"
                >
                    <DialogHeader>
                        <DialogTitle className="font-display text-3xl">Voir Total</DialogTitle>
                        <DialogDescription className="text-white/55">
                            Information privée — ne la montrez pas aux autres joueurs.
                        </DialogDescription>
                    </DialogHeader>
                    <p className="text-center" data-testid="reveal-total-text">
                        Le Total de {view.reveal?.targetName} est{" "}
                        <span className="font-display text-4xl font-semibold text-[#D4AF37]">
                            {formatTotal(view.reveal?.total ?? 0)}
                        </span>
                    </p>
                    <DialogFooter>
                        <Button
                            data-testid="reveal-ack-button"
                            onClick={() => send({ type: "ACK_REVEAL", playerId: me.id })}
                            className="bg-[#D4AF37] font-semibold uppercase tracking-[0.18em] text-[#0A0708] hover:bg-[#E5C463]"
                        >
                            J'ai vu
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* --- Présentation du début de partie --- */}
            <AnimatePresence>
                {introActive && currentPlayer && createPortal(
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-[10000] flex items-center justify-center bg-[#0A0708]/92 px-6 backdrop-blur-xl"
                        data-testid="game-start-overlay"
                    >
                        <motion.div
                            initial={{ opacity: 0, y: 24, scale: 0.96 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            transition={{ duration: 0.55, ease: [0.22, 1, 0.36, 1] }}
                            className="relative w-full max-w-lg overflow-hidden rounded-2xl border border-[#D4AF37]/30 bg-[#120D0F] p-9 text-center shadow-[0_0_100px_rgba(212,175,55,0.12)]"
                        >
                            <motion.div
                                className="absolute inset-x-0 top-0 h-px bg-[#D4AF37]"
                                animate={{ opacity: [0.25, 1, 0.25] }}
                                transition={{ duration: 1.4, repeat: Infinity }}
                            />
                            <span className="eyebrow-label">La partie commence</span>
                            <h2 className="mt-3 font-display text-5xl font-semibold tracking-tight">TOTAL</h2>
                            <div className="mx-auto mt-7 h-24 w-24 rounded-full p-1 ring-2 ring-[#D4AF37]/70 ring-offset-4 ring-offset-[#120D0F]">
                                <img src={currentPlayer.avatar} alt={`Avatar de ${currentPlayer.name}`} className="h-full w-full rounded-full object-cover" />
                            </div>
                            <p className="mt-6 text-sm uppercase tracking-[0.22em] text-white/40">Le premier joueur est</p>
                            <p className="mt-2 font-display text-3xl font-semibold text-[#D4AF37]">{currentPlayer.name}</p>
                            <p className="mt-4 text-xs text-white/40">Prépare-toi. Ton tour commence dans un instant.</p>
                        </motion.div>
                    </motion.div>,
                    document.body,
                )}
            </AnimatePresence>

            {/* --- Victoire --- */}
            {finished &&
                createPortal(
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        className="fixed inset-0 z-[9999] flex items-center justify-center bg-[#0A0708]/92 px-6 backdrop-blur-xl"
                        data-testid="victory-overlay"
                    >
                        <motion.div
                            initial={{ opacity: 0, y: 30, scale: 0.94 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            transition={{ duration: 0.55, ease: [0.22, 1, 0.36, 1] }}
                            className="relative w-full max-w-lg overflow-hidden rounded-2xl border border-[#D4AF37]/35 bg-[#120D0F] p-9 text-center shadow-[0_0_100px_rgba(212,175,55,0.14)]"
                        >
                            <div className="absolute inset-x-0 top-0 h-px bg-[#D4AF37]" />
                            <span className="eyebrow-label">Total correct</span>
                            <div className="mx-auto mt-5 h-24 w-24 rounded-full p-1 ring-2 ring-[#D4AF37] ring-offset-4 ring-offset-[#120D0F] shadow-[0_0_45px_rgba(212,175,55,0.2)]">
                                <img
                                    src={view.players.find((p) => p.id === view.winnerId)?.avatar}
                                    alt="Avatar du gagnant"
                                    className="h-full w-full rounded-full object-cover"
                                />
                            </div>
                            <p className="mt-6 text-xs uppercase tracking-[0.24em] text-white/35">Victoire</p>
                            <p className="mt-1 font-display text-5xl font-semibold text-[#D4AF37]">
                                {view.players.find((p) => p.id === view.winnerId)?.name}
                            </p>
                            {view.lastEvent?.type === "total_success" && (
                                <div className="mx-auto mt-5 max-w-md rounded-xl border border-white/[0.06] bg-white/[0.025] px-5 py-4">
                                    <p className="font-mono text-sm text-white/65">{view.lastEvent.expression}</p>
                                    <p className="mt-2 text-xs text-white/35">= {view.lastEvent.result} · cible {formatTotal(view.lastEvent.target)}</p>
                                </div>
                            )}
                            <div className="mt-7 flex justify-center gap-3">
                                <Button
                                    data-testid="restart-game-button"
                                    onClick={onRestart}
                                    className="bg-[#D4AF37] font-semibold uppercase tracking-[0.18em] text-[#0A0708] hover:bg-[#E5C463]"
                                >
                                    <RotateCcw size={14} className="mr-2" /> Nouvelle partie
                                </Button>
                                <Button variant="ghost" data-testid="victory-quit-button" onClick={onQuit}>
                                    Quitter
                                </Button>
                            </div>
                        </motion.div>
                    </motion.div>,
                    document.body,
                )}
        </div>

    );
}
