import { useCallback, useEffect, useRef, useState } from "react";
import { io } from "socket.io-client";

const SERVER_URL = process.env.REACT_APP_MASCARADE_SERVER_URL;

export default function useNetworkOneUpRoom() {
    const socketRef = useRef(null);
    const [room, setRoom] = useState(null); // { code, phase, hostPlayerId, seats, view }
    const [myPlayerId, setMyPlayerId] = useState(null);
    const [connectError, setConnectError] = useState(null);

    useEffect(() => {
        const socket = io(SERVER_URL, { transports: ["websocket"] });
        socketRef.current = socket;
        socket.on("room:update", setRoom);
        socket.on("connect_error", () => setConnectError("Connexion au serveur impossible."));
        return () => socket.disconnect();
    }, []);

    const createRoom = useCallback(({ name, avatar, isPublic, questionCount, roundTypes }) => {
        return new Promise((resolve) => {
            socketRef.current.emit("lobby:create", { game: "oneup", name, avatar, isPublic, questionCount, roundTypes }, (res) => {
                if (res.ok) setMyPlayerId(res.playerId);
                resolve(res);
            });
        });
    }, []);

    const joinRoom = useCallback(({ code, name, avatar }) => {
        return new Promise((resolve) => {
            socketRef.current.emit("lobby:join", { code, name, avatar }, (res) => {
                if (res.ok) setMyPlayerId(res.playerId);
                resolve(res);
            });
        });
    }, []);

    const listPublicRooms = useCallback(() => {
        return new Promise((resolve) => {
            socketRef.current.emit("lobby:list-public", { game: "oneup" }, (res) => resolve(res.rooms ?? []));
        });
    }, []);

    const startGame = useCallback(() => {
        socketRef.current.emit("lobby:start", {});
    }, []);

    const answer = useCallback((payload) => {
        socketRef.current.emit("game:action", { type: "answer", payload });
    }, []);

    const leaveRoom = useCallback(() => {
        socketRef.current.disconnect();
        socketRef.current.connect();
        setRoom(null);
        setMyPlayerId(null);
    }, []);

    const isHost = Boolean(room && myPlayerId && room.hostPlayerId === myPlayerId);

    return {
        room,
        view: room?.view ?? null,
        myPlayerId,
        isHost,
        connectError,
        createRoom,
        joinRoom,
        listPublicRooms,
        startGame,
        answer,
        leaveRoom,
    };
}
